type ReactionResult = {
  itemId: string;
  reacted: boolean;
  count: number;
};

let controller: AbortController | undefined;
async function load(q: string) {
  controller?.abort();
  controller = new AbortController();
  const response = await fetch(`/search?q=${encodeURIComponent(q)}`, {
    signal: controller.signal,
  });
  return response.json();
}

